<?php $title="Bicycle Catalog";require "includes/header.php";$r=$conn->query("SELECT * FROM bicycles ORDER BY id DESC");?><div class="section-title"><div><h2>🚲 Bicycle Catalog</h2><p class="muted">Models, pricing, stock and AI tags.</p></div><a class="btn primary" href="add_bicycle.php">+ Add Bicycle</a></div><div class="card"><input id="q" class="search" onkeyup="filterTable('q','t')" placeholder="Search..."><table id="t"><thead><tr><th>Model</th><th>Category</th><th>Price</th><th>Stock</th><th>AI Tag</th></tr></thead><tbody><?php while($x=$r->fetch_assoc()):?><tr><td><b><?=e($x["name"])?></b><br><?=e($x["sku"])?></td><td><?=e($x["category"])?></td><td><?=money($x["price"])?></td><td><?=$x["stock"]?></td><td><span class="badge"><?=e($x["ai_tag"])?></span></td></tr><?php endwhile;?></tbody></table></div><?php require "includes/footer.php";?>